with ins as (insert into public.artist_sound_tags (artist_slug,tag,source_url) select x.s,x.tag,x.u from json_to_recordset('[{"s":"bombie","tag":"groovy, boppy, hypnotic, and vibrant","u":"https://www.mixcloud.com/boxoutfm/boxout-wednesdays-248-bombie-23-08-2023/"},{"s":"dreamstates","tag":"lo-fi breakbeats, electro, garage or acid","u":"https://www.mixcloud.com/dreamstates/"},{"s":"girls-night-out","tag":"industrial soundscapes crossing krautrock, post-punk, EBM, wave and new beat","u":"https://www.mixcloud.com/boxoutfm/the-waiting-room-001-girls-night-out-22-03-2018/"},{"s":"kandy-kuri","tag":"atmospheric club selections, spanning across techno, breaks, bass","u":"https://www.mixcloud.com/FOUNDATION_FM/foundationfm-friday-takeover-filth-inc-w-kandy-kuri/"},{"s":"shama-anwar","tag":"Unapologetically unique take on hip-hop and electronic music","u":"https://www.mixcloud.com/boxoutfm/world-of-echo-001-shama-anwar-22-06-2019/"},{"s":"shama-anwar","tag":"Trap vibes","u":"https://www.mixcloud.com/drmartens/shama-anwar-dj-set-dr-martens-on-air-camden/"},{"s":"shama-anwar","tag":"Lush jazz numbers","u":"https://www.mixcloud.com/boxoutfm/chai-and-chill-048-shama-anwar-03-02-2019/"}]'::json) as x(s text,tag text,u text) join public.artists a on a.slug=x.s on conflict (artist_slug,tag) do nothing returning 1) select count(*) from ins;